function firstWelcomeReply(history, event, welcome, replies = {}) {
  if (!welcome.trim() || !history.complete || history.hasGaps ||
      event.type !== "message.received" || event.accountId !== history.accountId ||
      event.userId !== history.userId || event.conversationId !== history.conversationId ||
      !event.message || event.message.senderId !== history.userId ||
      event.message.direction !== "incoming" || event.message.type !== "text") return false;
  const stickers = new Set(history.messages.filter(m => m.type === "sticker").map(m => m.messageId));
  const rows = history.messages.filter(m => m.type !== "sticker");
  if (rows.length < 2) return false;
  const first = rows[0], last = rows[rows.length - 1];
  if (first.direction !== "outgoing" || first.type !== "text" || first.text !== welcome ||
      (first.replyToMessageId && !stickers.has(first.replyToMessageId))) return false;
  const automaticTexts = new Set(["ask_subscription", "explain_channel", "bot_question"].map(key => replies[key]).filter(text => typeof text === "string" && text.trim()));
  const parents = new Set([first.messageId, ...stickers]);
  let chars = 0;
  let previous = first;
  for (const message of rows.slice(1)) {
    if (!Number.isFinite(Date.parse(message.sentAt)) || Date.parse(message.sentAt) <= Date.parse(first.sentAt)) return false;
    if (message.direction === "outgoing") {
      if (previous.direction !== "incoming" || message.senderId !== first.senderId ||
          message.type !== "text" || !automaticTexts.has(message.text) ||
          (message.replyToMessageId && !parents.has(message.replyToMessageId))) return false;
      parents.add(message.messageId);
      previous = message;
      chars = 0;
      continue;
    }
    if (message.direction !== "incoming" || message.senderId !== history.userId ||
        message.type !== "text" || !message.text.trim() ||
        Date.parse(message.sentAt) <= Date.parse(first.sentAt) ||
        (message.replyToMessageId && !parents.has(message.replyToMessageId))) return false;
    chars += message.text.length;
    if (chars > 2000) return false;
    parents.add(message.messageId);
    previous = message;
  }
  return last.direction === "incoming" && last.messageId === event.messageId && last.messageId === event.message.messageId &&
    last.text === event.message.text && last.sentAt === event.message.sentAt;
}

const output = [];
for (const [i, item] of $input.all().entries()) {
  const { history, settings } = item.json;
  if (!history || !settings || typeof settings.welcomeText !== "string") continue;
  if (!firstWelcomeReply(history, item.json, settings.welcomeText, settings.replies)) continue;
  const messages = history.messages.filter(m => m.type !== "sticker");
  if (JSON.stringify(messages).length > 16000) continue;
  const subscriptionOnly = messages.slice(1).some(m => m.direction === "outgoing");
  const outgoing = messages.slice(1).filter(m => m.direction === "outgoing");
  const allowChannelExplanation = outgoing.at(-1)?.text === settings?.replies?.ask_subscription &&
    !outgoing.some(m => m.text === settings?.replies?.explain_channel);
  output.push({ ...item, json: { ...item.json, subscriptionOnly, allowChannelExplanation,
    replyGroupKey: `welcome-reply:${history.accountId}:${history.userId}:${messages[0].messageId}`,
    historySnapshot: JSON.stringify({ ...history, messages }) }, pairedItem: { item: i } });
}
return output;
